<x-dashboard-layout>
<x-slot name="title">Kelola Periode</x-slot><x-slot name="breadcrumb">Kelola Periode</x-slot>
<div class="space-y-5"><div class="flex justify-between items-center"><h1 class="text-2xl font-bold">Kelola Periode Bantuan</h1><a class="text-blue-700" href="{{ route('penyaluran.page') }}">Kembali ke Penyaluran</a></div>
<div class="rounded-xl border bg-white p-5 space-y-4"><h2 id="judul-form" class="font-bold">Tambah Periode</h2>
<form id="form-periode" class="grid gap-3 md:grid-cols-3"><label>Nama periode<input id="nama" required maxlength="150" class="mt-1 block w-full rounded-lg border p-2"></label><label>Tanggal mulai<input id="mulai" type="date" required class="mt-1 block w-full rounded-lg border p-2"></label><label>Tanggal selesai<input id="selesai" type="date" required class="mt-1 block w-full rounded-lg border p-2"></label><div class="flex gap-2"><button class="rounded-lg bg-blue-700 px-4 py-2 text-white">Simpan</button><button type="button" id="reset-form" class="rounded-lg border px-4 py-2">Batal Edit</button></div></form><p id="pesan" role="status" class="text-sm"></p></div>
<div class="overflow-x-auto rounded-xl border bg-white p-4"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Periode</th><th class="p-3">Mulai</th><th class="p-3">Selesai</th><th class="p-3">Aksi</th></tr></thead><tbody id="daftar-periode"></tbody></table></div></div>
<script>
(()=>{let rows=[],editing=null;const $=id=>document.getElementById(id),csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';
const date=v=>v?String(v).slice(0,10):'';
const api=async(url,method='GET',data)=>{const r=await fetch(url,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(', ')||d.message||'Permintaan gagal');return d;};
const reset=()=>{editing=null;$('form-periode').reset();$('judul-form').textContent='Tambah Periode';};
async function load(){try{rows=(await api('/api/periode')).data;const tbody=$('daftar-periode');tbody.replaceChildren();if(!rows.length){const tr=tbody.insertRow();const td=tr.insertCell();td.colSpan=4;td.textContent='Belum ada periode.';return;}rows.forEach(p=>{const tr=tbody.insertRow();[p.nama_periode,date(p.tgl_mulai),date(p.tgl_selesai)].forEach(v=>{const td=tr.insertCell();td.className='p-3 border-b';td.textContent=v;});const td=tr.insertCell();td.className='p-3 border-b';const edit=document.createElement('button');edit.textContent='Edit';edit.className='mr-3 text-blue-700';edit.onclick=()=>{editing=p.id;$('nama').value=p.nama_periode;$('mulai').value=date(p.tgl_mulai);$('selesai').value=date(p.tgl_selesai);$('judul-form').textContent='Edit Periode';window.scrollTo({top:0,behavior:'smooth'});};const del=document.createElement('button');del.textContent='Hapus';del.className='text-red-700';del.onclick=async()=>{if(!confirm('Hapus periode ini?'))return;try{await api('/api/periode/'+p.id,'DELETE');$('pesan').textContent='Periode dihapus.';load();}catch(e){$('pesan').textContent=e.message;}};td.append(edit,del);});}catch(e){$('pesan').textContent=e.message;}}
$('form-periode').onsubmit=async e=>{e.preventDefault();try{await api('/api/periode'+(editing?'/'+editing:''),editing?'PUT':'POST',{nama_periode:$('nama').value,tgl_mulai:$('mulai').value,tgl_selesai:$('selesai').value});$('pesan').textContent='Periode berhasil disimpan.';reset();load();}catch(e){$('pesan').textContent=e.message;}};
$('reset-form').onclick=reset;load();})();
</script></x-dashboard-layout>
